      "action_name": "auto-first_samp_clk_timescale",
      "description": "获取/设置首个采样时钟时间的时间尺度",
      "description_en": "get/set the timescale for the first sample clock time"
    },
    {
      "action_name": "auto-first_samp_clk_when",
      "description": "获取/设置首个采样时钟时间",
      "description_en": "get/set the time of the first sample clock"
    },
    {
      "action_name": "auto-first_samp_timestamp_enable",
      "description": "获取/设置是否启用首个样本时间戳",
      "description_en": "get/set whether the first sample timestamp is enabled"
    },
    {
      "action_name": "auto-first_samp_timestamp_timescale",
      "description": "获取/设置首个样本时间戳的时间尺度",
      "description_en": "get/set the timescale for the first sample timestamp"
